// SP Trading API v1 — the CONTRACT, and nothing else: scopes, request and answer schemas, and the table of operations.
//
// This file is pure (zod only: no configuration, no database, no signer), so that the OpenAPI document can be generated by a
// script and by a test without starting anything. routes.ts registers exactly these operations (one handler per `id`, a missing
// or extra handler fails at start-up), and openapi.ts renders exactly this table: the document cannot drift from the server.
import { z } from 'zod';

export const TRADING_PREFIX = '/api/v1/trading';
export const DEVELOPER_PREFIX = '/api/v1/developer';
export const API_VERSION = '1.0.0';

// ---------------------------------------------------------------------------------------------------------------- scopes
/** The closed list. There is deliberately NO scope for keys, the recovery phrase, signer administration, security settings,
 *  API-key management or mandate approval: those routes are outside TRADING_PREFIX, and a key opens nothing outside it. */
export const SCOPES = ['wallet:read', 'markets:read', 'orders:read', 'orders:prepare', 'orders:execute', 'orders:cancel', 'positions:read', 'positions:manage',
  'strategies:read', 'strategies:manage', 'agents:read', 'agents:manage'] as const;
export type Scope = (typeof SCOPES)[number];
export const ScopeSchema = z.enum(SCOPES);
/** route scope meaning "any authenticated principal" (the owner session or any valid key) — used by the OpenAPI document only */
export const ANY_SCOPE = '*' as const;
export type RouteScope = Scope | typeof ANY_SCOPE;
/** Scopes that would make a venue or the signer act. On a key they are INERT without a trading mandate bound to the key
 *  (`mandate_required`), and a scope is never what bounds execution: the signer-enforced mandate is. */
export const EXECUTION_SCOPES: readonly Scope[] = ['orders:execute', 'orders:cancel', 'positions:manage', 'strategies:manage', 'agents:manage'];
export const isExecutionScope = (s: string): boolean => (EXECUTION_SCOPES as readonly string[]).includes(s);

// ---------------------------------------------------------------------------------------------------------------- key model
export const KEY_BOUNDS = { maxDays: 365, defaultRatePerMin: 120, maxRatePerMin: 600, maxKeys: 50, maxNotionalUsd: 100_000_000 } as const;
const Usd = z.number().positive().max(KEY_BOUNDS.maxNotionalUsd);
/** recorded at creation, enforced when execution is wired; `null` = no limit of this kind on the key (the mandate still bounds it) */
export const LimitsSchema = z.strictObject({ maxOrderNotionalUsd: Usd.nullable().default(null), maxDailyNotionalUsd: Usd.nullable().default(null) });
export type Limits = z.infer<typeof LimitsSchema>;
const Name = (max: number) => z.string().regex(/^[A-Za-z0-9._:\/-]+$/).min(1).max(max);
/** an empty list means "not restricted on this axis" */
export const RestrictionsSchema = z.strictObject({
  networks: z.array(Name(24)).max(60).default([]),
  /** venue or protocol ids: hyperliquid, gmx, dydx, spot */
  venues: z.array(Name(40)).max(20).default([]),
  /** instrument ids as returned by GET /markets, e.g. hyperliquid:BTC */
  instruments: z.array(Name(120)).max(200).default([]),
  /** source addresses allowed to use the key: IPv4/IPv6 addresses or CIDR blocks */
  ipAllow: z.array(z.string().regex(/^[0-9A-Fa-f:.]{2,45}(\/\d{1,3})?$/)).max(20).default([]),
});
export type Restrictions = z.infer<typeof RestrictionsSchema>;

export const KeyCreateSchema = z.strictObject({
  name: z.string().trim().min(1).max(60),
  scopes: z.array(ScopeSchema).min(1).max(SCOPES.length),
  /** required; at most one year */
  expiresInDays: z.number().int().min(1).max(KEY_BOUNDS.maxDays),
  limits: LimitsSchema.default({ maxOrderNotionalUsd: null, maxDailyNotionalUsd: null }),
  restrictions: RestrictionsSchema.default({ networks: [], venues: [], instruments: [], ipAllow: [] }),
  rateLimitPerMin: z.number().int().min(1).max(KEY_BOUNDS.maxRatePerMin).default(KEY_BOUNDS.defaultRatePerMin),
  mandateId: z.uuid().nullable().default(null),
});
export type KeyCreate = z.infer<typeof KeyCreateSchema>;
export const KeyChangesSchema = z.strictObject({
  name: z.string().trim().min(1).max(60).optional(), scopes: z.array(ScopeSchema).min(1).max(SCOPES.length).optional(),
  /** absolute expiry, ISO 8601; at most one year after the key's creation */
  expiresAt: z.iso.datetime().optional(), limits: LimitsSchema.optional(), restrictions: RestrictionsSchema.optional(),
  rateLimitPerMin: z.number().int().min(1).max(KEY_BOUNDS.maxRatePerMin).optional(), mandateId: z.uuid().nullable().optional(),
});
export type KeyChanges = z.infer<typeof KeyChangesSchema>;

// ---------------------------------------------------------------------------------------------------------------- webhooks
/** `emitted`: an event source exists in this version. The others are defined (name and payload) and wait for their source. */
export const WEBHOOK_EVENTS = [
  { event: 'key.revoked', emitted: true, description: 'an API key was revoked (or replaced by a rotation)', payload: '{ keyId, name, reason }' },
  { event: 'risk.kill_switch', emitted: true, description: 'the owner triggered the emergency halt of the signer', payload: '{ source: "signer", halted: true }' },
  { event: 'agent.updated', emitted: true, description: 'an agent changed mode through an owner action (engine-side transitions: pending wiring)', payload: '{ agentId, kind, state, mode }' },
  { event: 'order.updated', emitted: false, description: 'an order changed state (pending wiring: emitted by the unified order state machine)', payload: '{ orderId, mode, venue, instrument, status }' },
] as const;
export type WebhookEvent = (typeof WEBHOOK_EVENTS)[number]['event'];
export const WEBHOOK_EVENT_NAMES = WEBHOOK_EVENTS.map((e) => e.event) as [WebhookEvent, ...WebhookEvent[]];

// ---------------------------------------------------------------------------------------------------------------- shared shapes
const Dec = z.string().describe('decimal number as a string (never a float)');
const Ms = z.number().int().describe('milliseconds since the Unix epoch');
const Mode = z.enum(['paper', 'live']).describe('paper = simulated, live = a venue or on-chain account. The two are never merged in one figure.');
export const ErrorSchema = z.object({ error: z.string().describe('stable machine code'), message: z.string().describe('human-readable sentence (English)') });
const PartialError = z.object({ source: z.string(), message: z.string() });
const MarketId = z.string().min(1).max(120).describe('`venue:symbol` (e.g. `hyperliquid:BTC`, `spot:ETH`); a bare symbol is accepted when it is not ambiguous');

export const MarketRow = z.looseObject({
  id: z.string(), venue: z.string(), kind: z.enum(['perpetual', 'spot']), symbol: z.string(), base: z.string(), quote: z.string(), status: z.string(),
  mark: Dec.nullable(), ts: Ms.nullable().describe('time the source produced this row (venue read time, or the last consolidated bar for spot)'),
  stale: z.boolean().describe('true when the row is older than its freshness bound or the source could not be refreshed'),
});
const Candle = z.object({ ts: Ms, open: Dec, high: Dec, low: Dec, close: Dec, volume: Dec });
const Level = z.tuple([Dec, Dec]).describe('[price, size]');

const R = {
  markets: z.object({ markets: z.array(MarketRow), total: z.number().int().describe('rows matching the filters, before `limit`'), truncated: z.boolean(), errors: z.array(PartialError), ts: Ms }),
  market: z.looseObject({ market: MarketRow, instrument: z.looseObject({}).nullable(), ticker: z.looseObject({}).nullable(), quality: z.looseObject({}).nullable(), ts: Ms, source: z.string() }),
  orderbook: z.object({ id: z.string(), bids: z.array(Level), asks: z.array(Level), ts: Ms, stale: z.boolean(), source: z.string() }),
  candles: z.object({ id: z.string(), interval: z.string(), candles: z.array(Candle), ts: Ms.nullable(), stale: z.boolean(), source: z.string() }),
  balances: z.object({ asOf: z.string(), balances: z.array(z.looseObject({ network: z.string(), asset: z.string(), symbol: z.string(), decimals: z.number().int(), amount: z.string().nullable(), display: z.string().nullable(), error: z.string().nullable() })), errors: z.array(PartialError) }),
  portfolio: z.object({
    asOf: z.string(),
    wallet: z.object({ valueUsd: z.number().nullable(), priced: z.number().int(), unpriced: z.number().int(), pricesAsOf: z.string().nullable(), balances: z.array(z.looseObject({ network: z.string(), symbol: z.string(), display: z.string().nullable(), valueUsd: z.number().nullable() })) }),
    accounts: z.array(z.looseObject({ mode: Mode, venue: z.string(), accountId: z.string(), equity: Dec.nullable(), error: z.string().nullable() })),
    totals: z.object({ walletUsd: z.number().nullable(), liveVenueEquity: Dec.nullable(), paperEquity: Dec.nullable() }).describe('three separate figures; there is no sum across modes'),
    halted: z.boolean(), errors: z.array(PartialError),
  }),
  positions: z.object({ positions: z.array(z.looseObject({ id: z.string(), mode: Mode, venue: z.string(), accountId: z.string(), instrument: z.string().nullable(), side: z.enum(['long', 'short']), size: Dec, entryPrice: Dec, markPrice: Dec.nullable(), unrealizedPnl: Dec.nullable(), source: z.string() })), errors: z.array(PartialError), ts: Ms }),
  orders: z.object({ orders: z.array(z.looseObject({ id: z.string(), mode: Mode, venue: z.string(), accountId: z.string().nullable(), instrument: z.string().nullable(), side: z.string().nullable(), type: z.string(), status: z.string(), final: z.boolean().nullable(), createdAt: Ms, updatedAt: Ms })), ts: Ms }),
  order: z.looseObject({ order: z.looseObject({ id: z.string(), mode: Mode, venue: z.string(), status: z.string() }), fills: z.array(z.looseObject({})) }),
  strategies: z.object({ library: z.array(z.looseObject({ kind: z.enum(['spot', 'perp']), path: z.string(), sha256: z.string() })), versions: z.array(z.looseObject({ id: z.string(), agentId: z.string(), name: z.string(), version: z.string(), sha256: z.string(), status: z.string() })), errors: z.array(PartialError) }),
  agents: z.object({ agents: z.array(z.looseObject({ id: z.string(), kind: z.enum(['spot', 'perp']), name: z.string(), state: z.string(), mode: z.string(), tradingMode: z.enum(['research', 'paper', 'live']).nullable(), venue: z.string(), universe: z.array(z.string()), interval: z.string() })) }),
  risk: z.looseObject({
    killSwitch: z.object({ signerReachable: z.boolean(), signerHalted: z.boolean().nullable(), note: z.string() }),
    signerPolicy: z.looseObject({}).nullable(), capabilityLocks: z.array(z.object({ id: z.string(), on: z.boolean(), why: z.string() })),
    accounts: z.array(z.looseObject({ mode: Mode, venue: z.string(), accountId: z.string(), policy: z.looseObject({}).nullable(), halted: z.boolean().nullable() })), errors: z.array(PartialError), ts: Ms,
  }),
  activity: z.object({ items: z.array(z.looseObject({ kind: z.string(), at: z.string(), mode: Mode })) }),
  openapi: z.looseObject({ openapi: z.string() }),
};

// ---------------------------------------------------------------------------------------------------------------- requests
const Venue = z.string().max(40).optional().describe('venue id: hyperliquid, gmx, dydx, spot');
const Limit = (dflt: number, max: number) => z.coerce.number().int().min(1).max(max).default(dflt);
const SymbolParam = z.object({ symbol: MarketId });
const IdParam = z.object({ id: z.string().min(1).max(200) });
export const CANDLE_INTERVALS = ['1m', '5m', '15m', '1h', '4h', '1d'] as const;

export const OrderRequestSchema = z.strictObject({
  mode: Mode, accountId: z.uuid().optional().describe('paper account or venue account; required when the wallet has several on the venue'),
  instrument: MarketId, side: z.enum(['buy', 'sell']),
  type: z.enum(['limit', 'market', 'stop_market', 'stop_limit', 'take_profit_market', 'take_profit_limit']),
  size: Dec.regex(/^\d+(\.\d+)?$/), price: Dec.regex(/^\d+(\.\d+)?$/).optional(), triggerPrice: Dec.regex(/^\d+(\.\d+)?$/).optional(),
  reduceOnly: z.boolean().default(false), tif: z.enum(['gtc', 'ioc', 'alo']).default('gtc'), slippageBps: z.number().int().min(1).max(500).optional(),
  clientOrderId: z.string().regex(/^[A-Za-z0-9._:-]{8,100}$/).optional(),
});
const CloseBody = z.strictObject({ slippageBps: z.number().int().min(1).max(500).optional() });
const ReduceBody = z.strictObject({ fraction: Dec.regex(/^(0(\.\d+)?|1(\.0+)?)$/).describe('share of the position to close, in (0, 1]'), slippageBps: z.number().int().min(1).max(500).optional() });
const StrategyBody = z.strictObject({ kind: z.enum(['spot', 'perp']), path: z.string().min(1).max(200).describe('library path of the strategy'), agentId: z.uuid().optional() });
const BacktestBody = z.strictObject({ symbols: z.array(z.string().regex(/^[A-Z0-9]{2,15}$/)).min(1).max(12).optional(), interval: z.enum(['1h', '1d']).optional() });
const StartBody = z.strictObject({ mode: Mode, agentId: z.uuid().optional() });
const StopBody = z.strictObject({ reason: z.string().max(200).default('') });
const AgentBody = z.strictObject({ kind: z.enum(['spot', 'perp']), name: z.string().min(2).max(40), mission: z.string().max(400).default(''), universe: z.array(z.string().regex(/^[A-Z0-9]{2,15}$/)).min(1).max(12), interval: z.enum(['1h', '1d']).default('1h'), mode: Mode.default('paper') });

// ---------------------------------------------------------------------------------------------------------------- operations
export interface OperationSpec {
  /** operationId, and the key of the handler in routes.ts */
  id: string; method: 'GET' | 'POST' | 'DELETE';
  /** Fastify path relative to TRADING_PREFIX (`:name` parameters) */
  path: string; tag: 'Markets' | 'Portfolio' | 'Orders' | 'Positions' | 'Strategies' | 'Agents' | 'Risk' | 'Meta';
  scope: RouteScope; summary: string; description?: string;
  params?: z.ZodObject; query?: z.ZodObject; body?: z.ZodType; response?: z.ZodType;
  /** mutating call: `Idempotency-Key` is required (replay protection) */
  idempotent?: boolean;
  /** false: the route exists with its scope, validation and idempotency, and answers 501 `execution_not_wired` */
  implemented: boolean;
}
const NOT_WIRED = 'Not wired in this version: the call is authenticated, authorized, validated and checked for replay, then answers 501 `execution_not_wired`. It never answers 2xx.';
const read = (id: string, path: string, tag: OperationSpec['tag'], scope: RouteScope, summary: string, o: Partial<OperationSpec> = {}): OperationSpec => ({ id, method: 'GET', path, tag, scope, summary, implemented: true, ...o });
const write = (id: string, method: 'POST' | 'DELETE', path: string, tag: OperationSpec['tag'], scope: Scope, summary: string, o: Partial<OperationSpec> = {}): OperationSpec =>
  ({ id, method, path, tag, scope, summary, description: NOT_WIRED, idempotent: true, implemented: false, ...o });

export const OPERATIONS: readonly OperationSpec[] = [
  read('getOpenApi', '/openapi.json', 'Meta', ANY_SCOPE, 'This document', { response: R.openapi, description: 'OpenAPI 3.1 document generated from the route schemas. Any valid key or the owner session.' }),
  read('listMarkets', '/markets', 'Markets', 'markets:read', 'Instruments across venues (perpetuals) and the spot market-data symbols',
    { query: z.object({ venue: Venue, kind: z.enum(['perpetual', 'spot']).optional(), q: z.string().max(40).optional().describe('case-insensitive match on id, symbol or base'), limit: Limit(2000, 5000) }), response: R.markets,
      description: 'Each row carries the time its source produced it (`ts`) and a `stale` flag. A venue that cannot be read is listed in `errors`; when no source answers the call fails with 503.' }),
  read('getMarket', '/markets/:symbol', 'Markets', 'markets:read', 'One market: instrument, ticker and data quality',
    { params: SymbolParam, response: R.market, description: 'A bare symbol that exists on several venues answers 409 `ambiguous_symbol` with the candidates.' }),
  read('getOrderbook', '/markets/:symbol/orderbook', 'Markets', 'markets:read', 'Order book of one market',
    { params: SymbolParam, query: z.object({ depth: z.coerce.number().int().min(1).max(50).default(20) }), response: R.orderbook, description: 'Venues without an order book (GMX, spot data) answer 422 `no_orderbook`.' }),
  read('getCandles', '/markets/:symbol/candles', 'Markets', 'markets:read', 'Closed bars of one market',
    { params: SymbolParam, query: z.object({ interval: z.enum(CANDLE_INTERVALS).default('1h'), limit: Limit(200, 1000) }), response: R.candles }),
  read('getPortfolio', '/portfolio', 'Portfolio', 'wallet:read', 'Wallet value and derivative accounts, per mode', { response: R.portfolio,
    description: 'Wallet balances valued in USD, then every derivatives account with its `mode`. Paper and live are never added together.' }),
  read('getBalances', '/balances', 'Portfolio', 'wallet:read', 'On-chain balances of the wallet', { query: z.object({ network: z.string().max(24).optional() }), response: R.balances }),
  read('getActivity', '/activity', 'Portfolio', 'wallet:read', 'Wallet activity and fills, newest first', { query: z.object({ limit: Limit(100, 500) }), response: R.activity }),
  read('listPositions', '/positions', 'Positions', 'positions:read', 'Open positions, paper and live separated by `mode`',
    { query: z.object({ mode: Mode.optional(), venue: Venue }), response: R.positions }),
  read('listOrders', '/orders', 'Orders', 'orders:read', 'Orders, newest first',
    { query: z.object({ mode: Mode.optional(), venue: Venue, open: z.enum(['true', 'false']).optional().describe('true: only orders that are not final'), limit: Limit(100, 500) }), response: R.orders }),
  read('getOrder', '/orders/:id', 'Orders', 'orders:read', 'One order and its fills', { params: IdParam, response: R.order }),
  read('listStrategies', '/strategies', 'Strategies', 'strategies:read', 'Strategy library and the versions pinned to agents', { query: z.object({ kind: z.enum(['spot', 'perp']).optional() }), response: R.strategies }),
  read('listAgents', '/agents', 'Agents', 'agents:read', 'Trading agents', { response: R.agents }),
  read('getRisk', '/risk', 'Risk', 'positions:read', 'Risk state: kill switch, signer limits, capability locks, account policies', { response: R.risk }),

  write('previewOrder', 'POST', '/orders/preview', 'Orders', 'orders:prepare', 'Preview an order (risk check and estimate)', { body: OrderRequestSchema }),
  write('placeOrder', 'POST', '/orders', 'Orders', 'orders:execute', 'Place an order', { body: OrderRequestSchema }),
  write('cancelOrder', 'DELETE', '/orders/:id', 'Orders', 'orders:cancel', 'Cancel an order', { params: IdParam }),
  write('closePosition', 'POST', '/positions/:id/close', 'Positions', 'positions:manage', 'Close a position', { params: IdParam, body: CloseBody }),
  write('reducePosition', 'POST', '/positions/:id/reduce', 'Positions', 'positions:manage', 'Reduce a position', { params: IdParam, body: ReduceBody }),
  write('createStrategy', 'POST', '/strategies', 'Strategies', 'strategies:manage', 'Register a strategy version', { body: StrategyBody }),
  write('backtestStrategy', 'POST', '/strategies/:id/backtest', 'Strategies', 'strategies:manage', 'Run a backtest', { params: IdParam, body: BacktestBody }),
  write('startStrategy', 'POST', '/strategies/:id/start', 'Strategies', 'strategies:manage', 'Start a strategy', { params: IdParam, body: StartBody }),
  write('stopStrategy', 'POST', '/strategies/:id/stop', 'Strategies', 'strategies:manage', 'Stop a strategy', { params: IdParam, body: StopBody }),
  write('createAgent', 'POST', '/agents', 'Agents', 'agents:manage', 'Create an agent', { body: AgentBody }),
  write('startAgent', 'POST', '/agents/:id/start', 'Agents', 'agents:manage', 'Start an agent', { params: IdParam, body: StartBody }),
  write('stopAgent', 'POST', '/agents/:id/stop', 'Agents', 'agents:manage', 'Stop an agent', { params: IdParam, body: StopBody }),
];
export type OperationId = string;
export const operation = (id: string): OperationSpec => { const o = OPERATIONS.find((x) => x.id === id); if (!o) throw new Error(`unknown operation ${id}`); return o; };
